mapper.select:
SELECT 
FROM TBL_REGULATORY_AUTHORITY
WHERE DELETE_FLAG = 0

    AND AUTHORITY_CODE LIKE CONCAT('%', #{authorityCode}, '%')


    AND AUTHORITY_NAME LIKE CONCAT('%', #{authorityName}, '%')


    AND AUTHORITY_TYPE = #{authorityType}


    AND IS_ACTIVE = #{isActive}


    AND COMPANY_ID = #{companyId}

ORDER BY SORT_ORDER ASC, CREATED_TIME DESC

mapper.update:
UPDATE TBL_REGULATORY_AUTHORITY
SET IS_ACTIVE = #{isActive}, UPDATED_TIME = SYSDATE
WHERE AUTHORITY_ID = #{authorityId}
